// Sync window: today through +18 months. Long enough to cover any
// booking lead time; short enough that each sync is cheap.
const start = new Date();
start.setUTCHours(0, 0, 0, 0);
const end = new Date(start);
end.setUTCMonth(end.getUTCMonth() + 18);
const fmt = (d) => d.toISOString().slice(0, 10);
return [{ json: {
  window_start: fmt(start),
  window_end: fmt(end),
  timeMin: start.toISOString(),
  timeMax: end.toISOString(),
} }];

// Google Calendar returns each holiday as an all-day event with
// start.date = 'YYYY-MM-DD'. Multi-day spans get expanded by
// singleEvents=true so we don't need to enumerate ourselves.
const window = $('Compute Window').first().json;
const events = $input.first().json.items || [];
const holidays = events
  .map(e => ({
    date: (e.start && e.start.date) || (e.start && e.start.dateTime && e.start.dateTime.slice(0, 10)),
    name: e.summary || 'Holiday',
    surcharge: 1000,
  }))
  .filter(h => h.date && h.date >= window.window_start && h.date < window.window_end);
return [{ json: {
  window_start: window.window_start,
  window_end: window.window_end,
  holidays,
  source: 'google_calendar',
} }];
